// Scoins screens → Figma. Creates one page with a section per flow and a frame per screen.
// Generated by docs tooling; screens are embedded as 2x JPEG image fills.
const GROUPS = [{"name": "Wallet", "frames": [{"name": "Wallet / Active", "w": 390, "h": 1813, "b64": ""}, {"name": "Wallet / Cardholder", "w": 390, "h": 2105, "b64": ""}, {"name": "Wallet / Spent everything", "w": 390, "h": 1075, "b64": ""}, {"name": "Wallet / New user", "w": 390, "h": 1029, "b64": ""}, {"name": "Wallet / Reward landed", "w": 390, "h": 844, "b64": ""}]}, {"name": "Wallet sheets", "frames": [{"name": "Sheet / Rates", "w": 390, "h": 844, "b64": ""}, {"name": "Sheet / All activity", "w": 390, "h": 844, "b64": ""}, {"name": "Sheet / Transaction details", "w": 390, "h": 844, "b64": ""}]}, {"name": "Intro animation", "frames": [{"name": "Intro / 1 Close-up", "w": 390, "h": 844, "b64": ""}, {"name": "Intro / 2 Edge-on", "w": 390, "h": 844, "b64": ""}, {"name": "Intro / 3 Formation", "w": 390, "h": 844, "b64": ""}, {"name": "Intro / 4 Wallet", "w": 390, "h": 844, "b64": ""}]}, {"name": "Earn", "frames": [{"name": "Earn / Active", "w": 390, "h": 2251, "b64": ""}, {"name": "Earn / Cardholder", "w": 390, "h": 2370, "b64": ""}, {"name": "Earn / New user", "w": 390, "h": 2231, "b64": ""}]}, {"name": "Spend flow", "frames": [{"name": "Spend / 1 Choose", "w": 390, "h": 844, "b64": ""}, {"name": "Spend / 2 Review", "w": 390, "h": 844, "b64": ""}, {"name": "Spend / 3 Confirming", "w": 390, "h": 844, "b64": ""}, {"name": "Spend / 4 Success", "w": 390, "h": 844, "b64": ""}, {"name": "Spend / Bill amount", "w": 390, "h": 844, "b64": ""}, {"name": "Spend / Not enough Scoins", "w": 390, "h": 844, "b64": ""}]}, {"name": "Withdraw flow", "frames": [{"name": "Withdraw / 1 Amount and UPI ID", "w": 390, "h": 844, "b64": ""}, {"name": "Withdraw / 2 UPI ID check", "w": 390, "h": 844, "b64": ""}, {"name": "Withdraw / 3 OTP", "w": 390, "h": 844, "b64": ""}, {"name": "Withdraw / 4 OTP error", "w": 390, "h": 844, "b64": ""}, {"name": "Withdraw / 5 Processing", "w": 390, "h": 844, "b64": ""}, {"name": "Withdraw / 6 Success with confetti", "w": 390, "h": 844, "b64": ""}, {"name": "Withdraw / 7 Success", "w": 390, "h": 844, "b64": ""}]}]

async function run() {
  await figma.loadFontAsync({ family: 'Inter', style: 'Medium' })
  await figma.loadFontAsync({ family: 'Inter', style: 'Regular' })
  const page = figma.createPage()
  page.name = 'Scoins screens'
  await figma.setCurrentPageAsync(page)

  const GAP = 80, LABEL = 40, PAD = 80
  let y = 0
  const made = []
  for (const group of GROUPS) {
    const section = figma.createSection()
    section.name = group.name
    let x = PAD, tallest = 0
    for (const f of group.frames) {
      const frame = figma.createFrame()
      frame.name = f.name
      frame.resize(f.w, f.h)
      frame.cornerRadius = 0
      const image = figma.createImage(figma.base64Decode(f.b64))
      frame.fills = [{ type: 'IMAGE', imageHash: image.hash, scaleMode: 'FILL' }]
      const label = figma.createText()
      label.fontName = { family: 'Inter', style: 'Medium' }
      label.characters = f.name
      label.fontSize = 16
      label.fills = [{ type: 'SOLID', color: { r: 0.33, g: 0.34, b: 0.37 } }]
      section.appendChild(label)
      section.appendChild(frame)
      label.x = x; label.y = PAD
      frame.x = x; frame.y = PAD + LABEL
      x += f.w + GAP
      tallest = Math.max(tallest, f.h)
      made.push(frame)
    }
    section.resizeWithoutConstraints(x - GAP + PAD, PAD + LABEL + tallest + PAD)
    section.x = 0; section.y = y
    y += section.height + 160
  }
  figma.viewport.scrollAndZoomIntoView(made)
  figma.closePlugin(`Added ${made.length} Scoins screens on the "Scoins screens" page`)
}

run().catch((e) => figma.closePlugin('Could not import screens: ' + e.message))
